import fs from 'node:fs';

const path = 'barz/index.html';
let s = fs.readFileSync(path, 'utf8');
const original = s;

function replaceOnce(oldText, newText, label) {
  const count = s.split(oldText).length - 1;
  if (count !== 1) throw new Error(`${label}: expected 1 match, got ${count}`);
  s = s.replace(oldText, newText);
}

if (s.includes('v0.5.1 · 2026.08.26')) {
  console.log('Barz v0.5.1 patch already applied');
  process.exit(0);
}

replaceOnce('v0.5.0 · 2026.08.25', 'v0.5.1 · 2026.08.26', 'version');
replaceOnce('id="quickRapStatus">Beatを選ぶだけ</span></span><button class="quickRapBtn" id="quickRapBtn" type="button">FIND</button>', 'id="quickRapStatus">良質候補を準備中</span></span><button class="quickRapBtn" id="quickRapBtn" type="button">GO</button>', 'quick CTA');
