replaceOnce("const youtubeApiKey=$('#youtubeApiKey'),saveApiKeyBtn=$('#saveApiKey'),smartState=$('#smartState');const DRAFT_KEY='barz_draft_v1',MIX_KEY='barz_mix_v1',GENRE_KEY='barz_genre_v1',RADIO_KEY='barz_radio_v1',DB_NAME='barz_db_v1',STORE='sessions',IMPORT_KEY='barz_import_pending',API_KEY='barz_yt_api_v1',SMART_KEY='barz_smart_v1';", "const youtubeApiKey=$('#youtubeApiKey'),saveApiKeyBtn=$('#saveApiKey'),smartState=$('#smartState'),fallbackTools=$('.fallbackTools');const DRAFT_KEY='barz_draft_v1',MIX_KEY='barz_mix_v1',GENRE_KEY='barz_genre_v1',RADIO_KEY='barz_radio_v1',DB_NAME='barz_db_v1',STORE='sessions',IMPORT_KEY='barz_import_pending',API_KEY='barz_yt_api_v1',SMART_KEY='barz_smart_v1',CACHE_URL='./beat-cache.json';", 'cache constants');
