replaceOnce("function loadSmart(){smart.key=readApiKey();youtubeApiKey.value=smart.key;try{const c=JSON.parse(localStorage.getItem(SMART_KEY)||'null');if(c&&typeof c==='object')smart.candidates=c}catch(e){}setSmartState(smart.key?'自動選定ON · 候補を先読みする':'APIキーを一度保存すると、次から候補を先読みする',smart.key?'ok':'')}", "function loadSmart(){smart.key=readApiKey();youtubeApiKey.value=smart.key;try{const c=JSON.parse(localStorage.getItem(SMART_KEY)||'null');if(c&&typeof c==='object')smart.candidates=c}catch(e){}setSmartState('候補キャッシュを確認中…','')}", 'loadSmart');
replaceOnce("function primeSmartCandidate(tracks){const t=tracks&&tracks[0];if(!t||recording||radio.live||mix)return;try{mountPlayer(t.videoId,true)}catch(e){}}", `function primeSmartCandidate(tracks){const t=tracks&&tracks[0];if(!t||recording||radio.live||mix)return;try{mountPlayer(t.videoId,true)}catch(e){}}
async function loadBeatCache(force){if(smart.cacheLoaded&&!force)return true;try{const r=await fetch(CACHE_URL+'?v='+(force?Date.now():'051'),{cache:force?'no-store':'default'});if(!r.ok)throw new Error('cache '+r.status);const j=await r.json();if(!j||!j.slots||typeof j.slots!=='object')throw new Error('cache format');const at=Date.parse(j.generatedAt)||Date.now();Object.entries(j.slots).forEach(([slot,tracks])=>{if(!Array.isArray(tracks))return;smart.candidates[slot]={at,tracks:tracks.filter(x=>x&&validId(x.videoId)).map(x=>Object.assign(newTrack(x.videoId),x,{publishedAt:Number(x.publishedAt)||null,addedAt:Date.now()}))}});smart.cacheLoaded=true;smart.cacheAt=at;smart.cacheError='';saveSmart();const c=smart.candidates[smartSlot(genre,radio.mode)]?.tracks||[];if(c.length)primeSmartCandidate(c);setSmartState(c.length?'候補キャッシュ準備済み · '+c.length+'曲':'候補キャッシュ読込済み',c.length?'ok':'');return true}catch(e){smart.cacheLoaded=true;smart.cacheError=String(e&&e.message||e);setSmartState(smart.key?'キャッシュなし · 端末APIを使用':'キャッシュ未準備 · FALLBACKを確認',smart.key?'':'bad');return false}}`, 'cache loader');
replaceOnce("async function fetchSmart(force,g,m){g=g||genre;m=m||radio.mode;const slot=smartSlot(g,m),cached=smart.candidates[slot];if(!smart.key)return[];if(!force&&cached&&Date.now()-cached.at<21600000&&Array.isArray(cached.tracks)){primeSmartCandidate(cached.tracks);return cached.tracks}", "async function fetchSmart(force,g,m){g=g||genre;m=m||radio.mode;const slot=smartSlot(g,m),cached=smart.candidates[slot];if(!force&&cached&&Array.isArray(cached.tracks)&&cached.tracks.length){primeSmartCandidate(cached.tracks);return cached.tracks}if(!smart.key)return[];", 'fetchSmart cache first');
replaceOnce("function warmSmart(){if(smart.key)fetchSmart(false,genre,radio.mode)}", "async function warmSmart(){await loadBeatCache(false);await fetchSmart(false,genre,radio.mode);renderQuick()}", 'warmSmart');
